#!/usr/bin/env python3
from pathlib import Path
import json,hashlib,sys
root=Path(sys.argv[1]); out=Path(sys.argv[2]); checks=[]
def ck(i,ok,d):checks.append({'id':i,'passed':bool(ok),'detail':str(d)})
def txt(p):return (root/p).read_text()
mod='src/games/mk2/research/broadIndexedGraphicsCorpusCensus.ts'; panel='src/components/MK2FoundationPanel.tsx'; meta='src/appMetadata.ts'; pkg='package.json'; runner='scripts/run-mk2-broad-indexed-census.mjs'; audit='scripts/audit-mk2-o69.py'
for p in [mod,panel,meta,pkg,runner,audit]:ck('exists_'+p,(root/p).is_file(),p)
