p=txt(panel);ck('panel_import','broadIndexedGraphicsCorpusCensus' in p,'import');ck('panel_runs','executeMK2BroadIndexedGraphicsCorpusCensus' in p,'run');ck('panel_o69_json','mk2_broad_indexed_graphics_corpus_census.json' in p,'download');ck('panel_warning','Runtime consumers and palette ownership remain unestablished' in p,'warning');ck('panel_scope','O67–O69' in p,'scope');
m=txt(meta);ck('milestone','1E.3O.69' in m and 'Broad Indexed GRA Corpus Census' in m,'milestone');d=json.loads(txt(pkg));ck('package_script',d['scripts'].get('smoke:mk2-broad-indexed-census')=='node scripts/run-mk2-broad-indexed-census.mjs',d['scripts'].get('smoke:mk2-broad-indexed-census'));ck('mk1_workflow_untouched','smoke:unified-mk1-asset-archive' in d['scripts'],'mk1 script retained')
